window.RP_SESSION={"id":"S-4cb50bfd114a","messages":[{"id":"RP-II-0023946","time":"2026-01-18T19:44:00+09:00","room":"RP II","name":"진저","profile":"진저브레이브","identity":"reviewed","type":"dialogue","body":"-진저\n\n\"...뭔가 좋은 일이 생긴거 같은데.\"","characters":["P-11b5c9c4a5f1"]},{"id":"RP-II-0023947","time":"2026-01-18T19:45:00+09:00","room":"RP II","name":"머독","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 무슨 일 말이오 진저군? \"\n\n머독은 마른 찻닢을 씹으며 진저에게 말을 걸었다.","characters":["P-87b04eb56606"]},{"id":"RP-II-0023948","time":"2026-01-18T19:46:00+09:00","room":"RP II","name":"파림","profile":"주디스 던","identity":"reviewed","type":"dialogue","body":"“사람을 치매 노인내 취급 하는구려.. 불쌍한 처자이외다….”\n\n지붕에서 모든 상황을 지켜보고 있었던 파림은 혀를 끌끌 차며 한탄했다.","characters":["P-8b81c98a5096"]},{"id":"RP-II-0023949","time":"2026-01-18T19:49:00+09:00","room":"RP II","name":"진저","profile":"진저브레이브","identity":"reviewed","type":"dialogue","body":"-진저\n\n\"..약간..뭐라고 해야하지...새벽같은...느낌이랄까? 그런 일이 생기고 있는것만 같아.\"\n\n\"어둡고 한치앞도 볼수 없는 밤일지라도 결국엔 내일은 찾아오니까. 그런 희망찬 일이 어딘가에서 생긴것만 같달까..\"\n\n{확실하지는 않지만 명확한 새벽 바람을 느끼는 진저. 왜인지 답답했던 마음이 한결 나아지는것만 같은 편안한 감각에 묘하게 위로가 됩니다.}","characters":["P-11b5c9c4a5f1"]},{"id":"RP-II-0023950","time":"2026-01-18T19:56:00+09:00","room":"RP II","name":"머독","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"\" 그렇다면 곧 태양이 뜨겠군... \"\n\n머독은 그런 진저의 옆에서 팔짱을 낀 채 조용히 찻닢을 씹었습니다.\n\n묘한 적운이 흐르는 길드가 진저의 말처럼 어슴푸레한 새벽녘이라면.\n\n곧 해가 뜨겠죠.","characters":["P-87b04eb56606"]},{"id":"RP-II-0023951","time":"2026-01-18T19:56:00+09:00","room":"RP II","name":"머독","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"새벽은, 아침의 예고니까.","characters":["P-87b04eb56606"]},{"id":"RP-II-0023952","time":"2026-01-18T20:03:00+09:00","room":"RP II","name":"머독","profile":"어설픈 용 ⃢맹","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-87b04eb56606"]},{"id":"RP-II-0023953","time":"2026-01-18T20:03:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... to be continue.","characters":[]}]};
